/**
 * @method
 * @name chkSymblDoubleInput
 * @description 심볼 중복체크
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.chkSymblDoubleInput = async function (symblTyp, symbl, symblCd, dtsObj) {
    // 초기화
    scwin.glb.MSG_SYMBL_DOUBLE_INPUT = "";

    let str = "";
    if (symblTyp === '1' || symblTyp === '3') {
        str = '영문회사';
    } else if (symblTyp === '2') {
        str = '영문종목';
    }

    if (symbl === "") {
        await $c.win.alert("[" + str + "심볼]을 입력하세요.");
        return false;
    }

    if (symblTyp === '1') {
        if (symbl.length >= 7) {
            await $c.win.alert("[" + str + "심볼]을 6자리이내로 입력하세요.");
            return false;
        }
    } else if (symblTyp === '2' || symblTyp === '3') {
        if (symbl.length >= 8) {
            await $c.win.alert("[" + str + "심볼]을 7자리이내로 입력하세요.");
            return false;
        }
    }

    if (symblTyp === '3') symblTyp = '1';

    // let url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    // url += "&DIV_IDX=" + DIV_R_CHK_SYMBL;
    // url += "&SYMBL_TYP=" + symblTyp;
    // url += "&SYMBL=" + symbl;
    // dts_Symbl.DataID = encodeURI(url);
    // dts_Symbl.Reset();

    const reqMap = {
        symbl: symbl,
        symblTyp: symblTyp,
    };

    const sbmOptions = {
        id: "sbm_selectOneSymbl",
        action: "/api/listing/lstproc/listinvstg-common/select-one-symbl",
        method: "get",
        // ref : "dma_codReq",
        // target: "dlt_codRes=body.COM_CHG_RSN_CD",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

    let vCd = res.responseJSON.body.cd;
    let vNm = res.responseJSON.body.nm;

    // 서버에서 컬럼에 null로 올때가 있어서 임시로 방어로직 추가
    if ($c.util.isEmpty(vCd)) vCd = "";

    if (symblCd !== vCd) {
        let msg = ""
            + "이미 지정되어 있는 " + str + "심볼을 입력하셨습니다.</br>"
            + "다시 확인 하시고 입력 해 주십시오.</br></br>"
            + "중복 데이터 내용 : </br>"
            + "[" + vCd + "]" + vNm + " </br>"

        scwin.glb.MSG_SYMBL_DOUBLE_INPUT = msg;
        return false;
    } else {
        let msg = "입력한 " + str + "심볼을 사용할 수 있습니다";
        scwin.glb.MSG_SYMBL_DOUBLE_INPUT = msg;
        return true;
    }
};

/**
 * @method
 * @name chkSymblDoubleInput1
 * @description 심볼 중복체크
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.chkSymblDoubleInput1 = async function (symblTyp, symbl, symblCd) {
    let str = "";
    if (symblTyp === '1' || symblTyp === '3') {
        str = '영문회사';
    } else if (symblTyp === '2') {
        str = '영문종목';
    }

    if (symbl === "") {
        $c.win.alert("[" + str + "심볼]을 입력하세요."); return false;
    }

    if (symblTyp === '1') {
        if (symbl.length >= 7) {
            $c.win.alert("[" + str + "심볼]을 6자리이내로 입력하세요."); return false;
        }
    } else if (symblTyp === '2' || symblTyp === '3') {
        if (symbl.length >= 8) {
            $c.win.alert("[" + str + "심볼]을 7자리이내로 입력하세요."); return false;
        }
    }

    if (symblTyp === '3') symblTyp = '1';

    // let url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    // url += "&DIV_IDX=" + DIV_R_CHK_SYMBL;
    // url += "&SYMBL_TYP=" + symblTyp;
    // url += "&SYMBL=" + symbl;
    // dts_Symbl.DataID = encodeURI(url);
    // dts_Symbl.Reset();

    const reqMap = {
        symbl: symbl,
        symblTyp: symblTyp,
    };
    const sbmOptions = {
        id: "sbm_selectOneSymbl",
        action: "/api/listing/lstproc/listinvstg-common/select-one-symbl",
        method: "get",
        // ref : "dma_codReq",
        // target: "dlt_codRes=body.COM_CHG_RSN_CD",
        // submitDoneHandler : scwin.sbm_selectOneSymbl_submitdone,
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);
    // alert('[dts_Symbl.CountRow]'+dtsObj.CountRow);
    let vCd = res.responseJSON.body.cd;
    let vNm = res.responseJSON.body.nm;

    if (res.responseJSON.body.cd) {
        let msg = ""
            + "이미 지정되어 있는 " + str + "심볼을 입력하셨습니다.\n"
            + "다시 확인 하시고 입력 해 주십시오.\n\n"
            + "중복 데이터 내용 : \n"
            + "[" + vCd + "]" + vNm + " \n"

        MSG_SYMBL_DOUBLE_INPUT = msg;
        return false;
    } else {
        let msg = "입력한 " + str + "심볼을 사용할 수 있습니다";
        MSG_SYMBL_DOUBLE_INPUT = msg;
        return true;
    }
};

/**
 * @method
 * @name setPanReadOnly
 * @description panel에 포함된 editable controls 들을 readonly, disable 상태로 변환한다.
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.setPanReadOnly = function (o) {
    let e;

    if (o != undefined) {
        for (let i = 0; i < o.children.length; i++) {
            e = o.children.item(i);
            if (e.tagName.toUpperCase() === "OBJECT") {
                switch (e.classid) {
                    case "clsid:D7779973-9954-464e-9708-DA774CA50E13": // maskedit
                        e.readOnly = true;
                        break;
                    case "clsid:BB4533A0-85E0-4657-9BF2-E8E7B100D47E": // combo
                        e.enable2 = false;
                        break;
                    case "clsid:F73C0958-D8FE-43a5-9BB0-0F651C5A2BCC": // radio
                        e.enable = false;
                        break;
                    case "clsid:1455BE02-C41B-4115-B21C-32380507DC8F": // textarea
                        e.readOnly = true;
                        break;
                    case "clsid:71E7ACA0-EF63-4055-9894-229B056E9C31": // grid
                        e.editable = false;
                        break;
                }
            } else {
                if (e.tagName.toUpperCase() === "INPUT") {
                    switch (e.type.toUpperCase()) {
                        case "TEXT":
                            e.readOnly = true; // "readonly";
                            break;
                        case "CHECKBOX":
                            e.disabled = true; // "disabled";
                            break;
                    }
                } else {
                    if (e.tagName.toUpperCase() === "SELECT") {
                        switch (e.type.toUpperCase()) {
                            case "SELECT-ONE":
                                e.disabled = true; // "disabled";
                                break;
                        }
                    }
                }
            }
        }
    }
};

