/**
* @method
* @name isInArr
* @description
* @param
 * @hidden N
* @exception
* @example
*/
scwin.isInArr = function (o, ec) {
    for (let i = 0; i < ec.length; i++) {
        if (o === ec[i]) { return true; }
    }

    return false;
};

