/**
 * @method
 * @name clearPanel
 * @description panel에 포함된 editable controls들을 초기화한다.
 * ec array에 포함된 control은 대상에서 제외한다.
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.clearPanel = function (o, ec) {
    let e;

    if (o != undefined) {
        for (let i = 0; i < o.children.length; i++) {
            e = o.children.item(i);

            if (scwin.isInArr(e, ec)) { continue; }

            if (e.tagName.toUpperCase() === "OBJECT") {
                switch (e.classid) {
                    case "clsid:D7779973-9954-464e-9708-DA774CA50E13": // maskedit
                        e.text = "";
                        break;
                    case "clsid:BB4533A0-85E0-4657-9BF2-E8E7B100D47E": // combo
                        e.index = -1;
                        break;
                    case "clsid:F73C0958-D8FE-43a5-9BB0-0F651C5A2BCC": // radio
                        e.codeValue = "";
                        break;
                    case "clsid:1455BE02-C41B-4115-B21C-32380507DC8F": // textarea
                        e.text = "";
                        break;
                    case "clsid:71E7ACA0-EF63-4055-9894-229B056E9C31": // grid
                        break;
                }
            } else {
                if (e.tagName.toUpperCase() === "INPUT") {
                    switch (e.type.toUpperCase()) {
                        case "TEXT":
                            e.value = "";
                            break;
                        case "CHECKBOX":
                            e.checked = false;
                            break;
                    }
                } else {
                    if (e.tagName.toUpperCase() === "SELECT") {
                        switch (e.type.toUpperCase()) {
                            case "SELECT-ONE":
                                e.disabled = false; // "disabled";
                                break;
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name encodeNSession
 * @description encodeURI 함수의 인수에 session정보를 덧붙여서 반환한다.
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.encodeNSession = function (uri) {
    let sid = "";

    try { sid = scwin.fr_SecuGrpId; } catch (e) { } // 화면에 fr_SecuGrpId가 선언되지 않았다면 모든 증권그룹에 대하여 처리

    return encodeURI(uri +
        "&EMP_NO=" + js_emp_no +
        "&EMP_NM=" + js_emp_nm +
        "&EMAIL=" + js_email +
        "&DEP_CD=" + js_dep_cd +
        "&MARKET=" + js_market +
        "&USR_TP_CD=" + js_usr_tp_cd +
        "&DUTY=" + js_duty +
        "&DUTY_CHRG=" + js_duty_chrg +
        "&SNDLOC=" + js_sndloc +
        "&SECUGRP_ID=" + sid
    );
};

