/**
 * @method
 * @name isNewValueForDataSet
 * @description 팝업창에서 선택한 사항이 이미 DataSet에 있는지 검증한다.
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.isNewValueForDataSet = function (dts, colName, checkValue) {
    for (let i = 1; i <= dts.getRowCount(); i++) {
        if (dts.getCellData(i, colName) === checkValue) {
            $c.win.alert("이미 선택하신 사유가 있습니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name checkDdTm
 * @description 일자,시간 체크 함수
 * isCheckCurDate : 오늘 날짜를 포함해서 비교를 할지 여부 ( 유가 : 미포함, 코스닥 : 포함 )
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.checkDdTm = function (gubun, obj, msg, includeCurDate) {
    if (gubun === "DD") {
        if (obj.text.length !== 8) { $c.win.alert("[" + msg + "일]을 정확히 입력하세요."); obj.focus(); return false; }

        let vCurDate = $c.date.getServerDateTime();
        if (includeCurDate) {
            if (vCurDate > obj.getValue()) {
                $c.win.alert("[" + msg + "일]을 현재일 이후로 입력하세요."); obj.focus(); return false;
            }
        }
        else {
            if (vCurDate >= obj.getValue()) {
                $c.win.alert("[" + msg + "일]을 익일 이후로 입력하세요."); obj.focus(); return false;
            }
        }
    }
    else if (gubun === "TM") {
        if (obj.text.length === 0) return true;
        if (obj.text.length !== 6) { $c.win.alert("[" + msg + "시간]을 [시,분,초]까지 정확히 입력하세요."); obj.focus(); return false; }

        let tmp = obj.text;
        if (Number(tmp.substring(0, 2)) > 23) { $c.win.alert("[" + msg + "시간중 시]를 정확히 입력하세요."); obj.focus(); return false; }
        if (Number(tmp.substring(2, 4)) > 59) { $c.win.alert("[" + msg + "시간중 분]을 정확히 입력하세요."); obj.focus(); return false; }
        if (Number(tmp.substring(4)) > 59) { $c.win.alert("[" + msg + "시간중 초]를 정확히 입력하세요."); obj.focus(); return false; }
    }
    else if (gubun === "TM2") {
        if (obj.text.length === 0) return true;
        if (obj.text.length !== 4) { $c.win.alert("[" + msg + "시간]을 [시,분]까지 정확히 입력하세요."); obj.focus(); return false; }

        let tmp = obj.text;
        if (Number(tmp.substring(0, 2)) > 23) { $c.win.alert("[" + msg + "시간중 시]를 정확히 입력하세요."); obj.focus(); return false; }
        if (Number(tmp.substring(2, 4)) > 59) { $c.win.alert("[" + msg + "시간중 분]을 정확히 입력하세요."); obj.focus(); return false; }

    }
    return true;
};

/**
 * @method
 * @name checkDdTm2
 * @description 일자,시간 체크 함수
 * isCheckCurDate : 오늘 날짜를 포함해서 비교를 할지 여부 ( 유가 : 미포함, 코스닥 : 포함 )
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.checkDdTm2 = function (gubun, obj, msg) {
    if (gubun === "DD") {
        if (obj.text.length !== 8) { $c.win.alert("[" + msg + "일]을 정확히 입력하세요."); obj.focus(); return false; }
    }
    else if (gubun === "TM") {
        if (obj.text.length === 0) return true;
        if (obj.text.length !== 6) { $c.win.alert("[" + msg + "시간]을 [시,분,초]까지 정확히 입력하세요."); obj.focus(); return false; }

        let tmp = obj.text;
        if (Number(tmp.substring(0, 2)) > 24) { $c.win.alert("[" + msg + "시간중 시]를 정확히 입력하세요."); obj.focus(); return false; }
        if (Number(tmp.substring(2, 4)) > 59) { $c.win.alert("[" + msg + "시간중 분]을 정확히 입력하세요."); obj.focus(); return false; }
        if (Number(tmp.substring(4)) > 59) { $c.win.alert("[" + msg + "시간중 초]를 정확히 입력하세요."); obj.focus(); return false; }

    }
    return true;
};

/**
 * @method
 * @name getRowIdx
 * @description 그리드에서 수정할때와  신규등록시 변경전 데이타의 ROWCONT 구하기
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.getRowIdx = function (vKey, dtsObj) {
    let vRow;
    if (vKey === "") { vRow = dtsObj.getRowCount(); }		// 신규등록시 
    else if (vKey !== "") { vRow = dtsObj.getRowPosition() - 1; }	// 수정시 

    return vRow;
};

/**
 * @method
 * @name getMstStatus
 * @description 관리종목지정(유) 관련해서 현재 업무를 저장할수 있는지 여부를 판단해줌
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.getMstStatus = async function (param_Dts, tpCd, obj, flag) {
    let isFlag = false;
    let url = "";

    // 현재 작업이 종목별일 경우
    if (flag) {
        url = "/administrativeIssue.do?method=searchAdministrativeIssue&DIV_IDX=" + scwin.glb.DIV_IDX_ADMISU_MST
            + "&TRS_IDX=" + scwin.TRS_IDX_NEWSEL2 + "&ISUR_CD=" + Isur_cd + "&ISU_CD=" + Isu_cd;
        // 현재 작업이 회사별일 경우
    } else {
        url = "/administrativeIssue.do?method=searchAdministrativeIssue&DIV_IDX=" + scwin.glb.DIV_IDX_ADMISU_MST
            + "&TRS_IDX=" + scwin.TRS_IDX_NEWSEL + "&ISUR_CD=" + Isur_cd;
    }

    const mstStatusOption = {
        id: "sbmMstStatus",
        action: encodeURI(url),
        method: "get",
        isProcessMsg: false
    };

    let res = await $c.sbm.executeDynamic(mstStatusOption, {});
    if (res.responseJSON.success === true) {
        param_Dts.setJSON(res.responseJSON.body);
    }

    /*
    관리종목지정업무구분코드
    0:관리종목지정
    1:관리종목사유변경
    2:관리종목사유및유의사항변경
    3:유의사항변경
    4:관리종목지정해제
    5:상장폐지기준적용유예
    6:상장폐지기준적용유예기간변경
    */

    let type = param_Dts.getCellData(1, "ADMISU_DESIGN_BZ_TP_CD");  // 관리종목지정업무구분코드
    let maxDate = param_Dts.getCellData(1, "MKTACT_ENFORCE_DD");       // 시행일
    let mktactApplObjTpCd = param_Dts.getCellData(1, "MKTACT_APPL_OBJ_TP_CD");   // 시장조치적용대상구분코드(1:종목별, 2:회사별)

    // 지정일자 체크
    if (maxDate >= obj.getValue()) {
        $c.win.alert($c.stf.getMessageParam("MSG-0020", ""));
        return false;
    }

    // 현재 작업이 종목별일 경우
    if (flag) {
        // 과거 이력이 종목일 경우 
        if (mktactApplObjTpCd === '1') {
            // 지정일 경우는 직전 이력이 해제여야 함
            if (tpCd === '0') {
                if (type === '4' || type == null) isFlag = true;
            }
            // 해제일경우는 직전이 해제가 아니여야 함
            else if (tpCd === '4' || tpCd === '5') {
                if (type !== '4' && type != null) isFlag = true;
            }
            // 상장폐지기준적용유예 기간변경일 경우는 직전이 유예여야 함
            else if (tpCd === '6') {
                if (type === '5') isFlag = true;
            }
            // 기타는 직전이 해제만 아니면됨. 
            else if (tpCd === '1' || tpCd === '2' || tpCd === '3') {
                if (type !== '4' && type != null) isFlag = true;
            }
            // 과거 이력이 회사일 경우
        } else if (mktactApplObjTpCd === '2') {
            isFlag = false;
        } else {
            isFlag = true;
        }

        // 현재 작업이 회사별일 경우
    } else {
        // 과거 이력이 종목별일 경우 
        if (mktactApplObjTpCd == null || mktactApplObjTpCd === '1') {
            isFlag = true;
            // 과거 이력이 회사별일 경우
        } else if (mktactApplObjTpCd === '2') {
            // 지정일 경우는 직전이 해제여야 함
            if (tpCd === '0') {
                if (type === '4' || type == null) isFlag = true;
            }
            // 해제일경우는 직전이 해제가 아니여야 함
            else if (tpCd === '4' || tpCd === '5') {
                if (type !== '4' && type != null) isFlag = true;
            }
            // 상장폐지기준적용유예 기간변경일 경우는 직전이 유예여야 함
            else if (tpCd === '6') {
                if (type === '5') isFlag = true;
            }
            // 기타는 직전이 해제만 아니면됨. 
            else if (tpCd === '1' || tpCd === '2' || tpCd === '3') {
                if (type !== '4' && type != null) isFlag = true;
            }
        }
    }

    if (!isFlag) $c.win.alert($c.stf.getMessageParam("MSG-0021", ""));

    return isFlag;
};

