            }
            // 해제일경우는 직전이 해제가 아니여야 함
            else if (tpCd === '0') {
                if (type !== '0' && type != null) isFlag = true;
            }
            // 기타는 직전이 해제만 아니면됨. 
            else if (tpCd === '2' || tpCd === '3' || tpCd === '4') {
                if (type !== '0' && type != null) isFlag = true;
            }
            // 과거 이력이 회사일 경우
        } else if (mktactApplObjTpCd === '2') {
            isFlag = false;
        } else {
            isFlag = true;
        }

        // 현재 작업이 회사별일 경우
    } else {
        // 과거 이력이 종목별일 경우 
        if (mktactApplObjTpCd == null || mktactApplObjTpCd === '1') {
            isFlag = true;
            // 과거 이력이 회사별일 경우
        } else if (mktactApplObjTpCd === '2') {
            // 지정일 경우는 직전이 해제여야 함
            if (tpCd === '1') {
                if (type === '0' || type == null) isFlag = true;
            }
            // 해제일경우는 직전이 해제가 아니여야 함
