            else if (tpCd === '2' || tpCd === '3' || tpCd === '4') {
                if (type !== '0' && type != null) isFlag = true;
            }
        }
    }

    if (!isFlag) $c.win.alert($c.stf.getMessageParam("MSG-0021", ""));

    return isFlag;
};

