/**
 * @method
 * @name getRecvDocProvider
 * @description 문서처리현황 프레임을 참조.
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.getRecvDocProvider = function () {
    // TODO Stage2: AS-IS 는 Gauce 프레임 src URL(frame.srcUrl)을 위치 기반(&-split)으로 파싱해
    // 전역(gIsurCd 등)을 세팅했다. WebSquare 에서는 진입 파라미터를 $c.util.getParameter(키) 로
    // 키 기반 조회하도록 소비처 확인 후 재작성한다.
    const frameObj = $p.getFrame();
    const url = (frameObj && typeof frameObj.getSrc === "function") ? (frameObj.getSrc() || "") : "";
    let arr = url.split("?");
    let arr2 = url.split("&");

    gIsurCd = arr2[1]; //
    gAcptNo = arr2[2]; //
    gSecugrpId = arr2[3]; //
    gMktTpCd = arr2[4]; //
    gComAbbrv = arr2[5]; // 회사명에 '&' 들어가는 경우가 있어 맨나중에 함(수정필요)

    // AS-IS frame.Provider("../"+쿼리) 는 path() 의 else 분기로 $p.parent() 와 동등 — 부모 프레임 반환
    return (arr.length >= 1 ? $c.win.getParent() : undefined);
};

