    }
};

/**
 * @method
 * @name checkBzDoubleInput
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.checkBzDoubleInput = async function (gIsurCd, gChdDD, gbzProcsNo, gListBzTpCd, pageId) {
    let reqMap = {};
    let svc = "";
    if (pageId === "STF09316") {
        // 종목변경에서 호출시
        reqMap.isuCd = gIsurCd;
        reqMap.mktactEnforceDd = gChdDD;
        reqMap.bzProcsNo = gbzProcsNo;
        svc = "/api/listing/lstproc/pf/isunmchg/double-check"
    } else {
        reqMap.isuCd = gIsurCd;
        reqMap.mktactEnforceDd = gChdDD;
        reqMap.bzProcsNo = gbzProcsNo;
        reqMap.listBzTpCd = gListBzTpCd;
        svc = "/api/listing/lstproc/stock/chglisting/check-double-input"
    }

    const sbmOptions = {
        id: "sbm_checkDoubleInput",
        action: svc,
        method: "get",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

    let vPROCS_DDTM = res.responseJSON.body.disclsProcsDdtm;
    let vPROCS_STAT_CD = res.responseJSON.body.disclsProcsStatCd;
    if (vPROCS_DDTM === null || vPROCS_DDTM === "") {
        return true;
    } else {
