/**
 * @method
 * @name checkAcntclsMM
 * @description desc 결산월체크
 * @param
 * @returns
 * @hidden N
 * @exception 
 * @migrationStatus
 * @example
 */
scwin.checkAcntclsMM = function (obj) {
    if (obj.length === 1) {
        $c.win.alert("[결산월]을 올바르게 입력하세요. 1월 -> 01월");
        obj.focus();
        return false;
    } else if (obj.length === 2) {
        if (parseInt(obj.getValue(), 10) > 12) {
            $c.win.alert("[결산월]이 12월을 초과하였습니다. 다시입력하세요");
            obj.focus();
            return false;
        }
    } else if (obj.length === 4) {
        if (parseInt(obj.getValue().substring(0, 2), 10) > 12) {
            $c.win.alert("[결산월]이 12월을 초과하였습니다. 다시입력하세요");
            obj.focus();
            return false;
        }
    }

    return true;
};

/**
 * @method
 * @name checkAcntclsMMDD
 * @description desc 결산월체크
 * @param
 * @returns
 * @hidden N
 * @exception 
 * @migrationStatus
 * @example
 */
scwin.checkAcntclsMMDD = function (obj) {
    if (obj.getValue().length !== 4) {
        $c.win.alert("[결산월일]을 올바르게 입력하세요. 1월1일 -> 01월01일"); obj.focus(); return false;
    }

    if (parseInt(obj.getValue().substring(0, 2), 10) > 12) {
        $c.win.alert("[입력월]이 12월을 초과하였습니다. 다시입력하세요");
        obj.focus();
        return false;
    }

    if (parseInt(obj.getValue().substring(2, 4), 10) > 31) {
        $c.win.alert("[입력일]이 31일을 초과하였습니다. 다시입력하세요"); obj.focus(); return false;
    }
    return true;
};

