/**
 * @method
 * @name setButtonDepCd
 * @description 
 * @param
 * @returns
 * @hidden N
 * @exception 
 * @migrationStatus
 * @example
 */
scwin.setButtonDepCd = async function (isurCd, userInfo, arrBtn) {

    if (userInfo.duty === 'Y' || userInfo.dutyChrg === 'Y') {
    } else {
        const param = {
            isurCd: isurCd
        };

        const sbmOptions = {
            id: "sbm_select-corp-dep-cd",
            method: "get",
            action: "/api/listing/common/stock/select-corp-dep-cd",
            isProcessMsg: false
        };

        const res = await $c.sbm.executeDynamic(sbmOptions, param);

        if (res.responseJSON.success) {
            if (userInfo.depCd !== res.responseJSON.body.depCd) {
                for (let i = 0; i < arrBtn.length; i++) {
                    arrBtn[i].setDisabled(true);
                }
            }
        }
    }
};

