/**
 * @method
 * @name bfReadSync
 * @description 변경 전 주식수 및 자본금 조회
 * @param
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.bfReadSync = async function (ibx_ISU_CD, ibx_LIST_DD, ibx_BF_ACC_ISU_SHRS, ibx_BF_ACC_ISU_CAP) {
    const searchReq = {
        "isuCd": ibx_ISU_CD.getValue(),
        "listDd": ibx_LIST_DD.getValue()
    };

    const sbmOptions = {
        id: "sbm_beforeIsuDetail",
        method: "get",
        action: "/api/listing/lstproc/newlist-isu/select-one-before-stkcert-isu",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions, searchReq);

    if (res.responseJSON.success) {
        if (res.responseJSON.body.bfAccIsuShrs !== null && res.responseJSON.body.bfAccIsuCap !== null) {
            ibx_BF_ACC_ISU_SHRS.setValue(res.responseJSON.body.bfAccIsuShrs);
            ibx_BF_ACC_ISU_CAP.setValue(res.responseJSON.body.bfAccIsuCap);
        } else { // 신규건
            ibx_BF_ACC_ISU_SHRS.setValue(res.responseJSON.body.bfAccIsuShrs);
            ibx_BF_ACC_ISU_CAP.setValue(res.responseJSON.body.bfAccIsuCap);
        }
    }
};

/**
 * @method
 * @name bfReadSync2
 * @description 변경전 주식수, 자본금 가져오기
 * @param
 * @returns
 * @hidden N
 * @exception 
 * @migrationStatus
 * @example
 */
scwin.bfReadSync2 = async function (dtsObj, txb_ISU_CD, edt_BF_ACC_ISU_SHRS, edt_BF_ACC_ISU_CAP) {
    const param = {
        isuCd: txb_ISU_CD.getValue()
    };

    const sbmOptions = {
        id: "sbm_before-isu-detail",
        method: "get",
        action: "/api/listing/lstproc/stock/issuance-manage/before-isu-detail",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions, param);
    if (res.responseJSON.success) {
        if (res.responseJSON.body.bfAccIsuShrs !== null && res.responseJSON.body.bfAccIsuCap !== null) {
            edt_BF_ACC_ISU_SHRS.setValue(res.responseJSON.body.bfAccIsuShrs);
            edt_BF_ACC_ISU_CAP.setValue(res.responseJSON.body.bfAccIsuCap);
        } else {
            edt_BF_ACC_ISU_SHRS.setValue(0);
            edt_BF_ACC_ISU_CAP.setValue(0);
        }
    }
};

/**
 * @method
 * @name gridNameChange
 * @description gridView의 HeaderValue 속성 변경
 * @param
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.gridNameChange = function (vSecuGrpId, topGrid, botGrid) {
    // debugger;
    if (vSecuGrpId === scwin.glb.SECUGRP_ID_DR) {
        // DR인 경우
        $p.getComponentById(topGrid).setHeaderValue("h_STKCERT_KIND_NM", "DR종류");
        $p.getComponentById(topGrid).setHeaderValue("h_ISU_SHRS", "발행DR수");

        $p.getComponentById(botGrid).setHeaderValue("h_ISU_SHRS", "총발행DR수");
        $p.getComponentById(botGrid).setHeaderValue("h_isu_kor_nm", "DR종류");
        $p.getComponentById(botGrid).setHeaderValue("h_isuShrs", "증감DR수");
        $p.getComponentById(botGrid).setColumnVisible("parval", false);// 액면가
        $p.getComponentById(botGrid).setColumnVisible("isuCap", false);// 증감상장자본금
        $p.getComponentById(botGrid).setColumnVisible("accIsuCap", false);// 변경후상장자본금
    } else {
        $p.getComponentById(topGrid).setHeaderValue("h_STKCERT_KIND_NM", "주식종류");
        $p.getComponentById(topGrid).setHeaderValue("h_ISU_SHRS", "증감주식수");

        $p.getComponentById(botGrid).setHeaderValue("h_ISU_SHRS", "총상장주식수");
        $p.getComponentById(botGrid).setHeaderValue("h_isu_kor_nm", "상장방식");
        $p.getComponentById(botGrid).setHeaderValue("h_isuShrs", "증감주식수");
        $p.getComponentById(botGrid).setColumnVisible("parval", true);// 액면가
        $p.getComponentById(botGrid).setColumnVisible("isuCap", true);// 증감상장자본금
        $p.getComponentById(botGrid).setColumnVisible("accIsuCap", true);// 변경후상장자본금
    }
};

